Lemmatheca.ModelTheory.Diagrams.signedDiagram_relation_fact.{u, v, w} {L : FirstOrder.Language} {M : Type w}
  [L.Structure M] {n : ℕ} (R : L.Relations n) (a : Fin n → M) :
  have γ := FirstOrder.Language.Relations.formula (Sum.inl R) fun i => (L.con (a i)).term;
  (FirstOrder.Language.Structure.RelMap R a → γ ∈ Lemmatheca.ModelTheory.Diagrams.signedDiagram L M) ∧
    (¬FirstOrder.Language.Structure.RelMap R a →
      FirstOrder.Language.Formula.not γ ∈ Lemmatheca.ModelTheory.Diagrams.signedDiagram L M)
